def detectar_encoding(caminho):
    from pathlib import Path
    dados = Path(caminho).read_bytes()

    if dados.startswith(b"\xef\xbb\xbf"):
        return "utf-8"

    try:
        dados.decode("utf-8")
        return "utf-8"
    except UnicodeDecodeError:
        return "latin-1"

